function P.arrestLoop(alive)
    while alive() do
        local okJob, why
        if not ensureCar(true) then noCar("pol")
        else
            okJob, why = ensureJob("Security")
            if not okJob then setStatus("pol", why) task.wait(3)
            else
                local tgt = nearest(P.targets(), function(p) return p.Character.HumanoidRootPart.Position end)
                if not tgt then
                    setStatus("pol", L["No wanted outlaws"])
                    task.wait(2)
                else
                    setStatus("pol", L["Chasing "] .. tgt.DisplayName)
                    local t0 = os.clock()
                    local function still()
                        local c = tgt.Character
                        return alive() and c and c.Parent and num(c:GetAttribute("CriminalExpireEpoch")) > os.time() and os.clock() - t0 < 25
                    end
                    S.gliding = true
                    while still() do
                        local tr = tgt.Character and tgt.Character:FindFirstChild("HumanoidRootPart")
                        local root, model = T.mover()
                        if not (tr and root) then break end
                        local goal = tr.Position + tr.AssemblyLinearVelocity * 0.15 + Vector3.new(0, 2, 0)
                        local d = goal - root.Position
                        if d.Magnitude > 120 then
                            T.go(goal, { alive = still, tol = 15 })
                            S.gliding = true
                        else
                            local tv = tr.AssemblyLinearVelocity
                            if d.Magnitude > 4 then
                                local sp = math.clamp(d.Magnitude * 4, tv.Magnitude, math.min(S.speed, speedCap()))
                                T.push(root, d.Unit, sp)
                                pcall(T.face, model, root, d.Unit)
                            else
                                T.push(root, tv.Magnitude > 1 and tv.Unit or Vector3.zero, tv.Magnitude)
                            end
                            RunService.Heartbeat:Wait()
                        end
                    end
                    T.stop()
                end
            end
        end
        task.wait(0.2)
    end
    setStatus("pol", nil)
end

local DR = { plat = nil, miles = 0 }
function DR.clear()
    if DR.plat then pcall(function() DR.plat:Destroy() end) DR.plat = nil end
end
onClean(DR.clear)
function DR.platform()
    if DR.plat and DR.plat.Parent then return DR.plat end
    local p = Instance.new("Part")
    p.Name = HttpService:GenerateGUID(false)
    p.Size = Vector3.new(90, 1, 90)
    p.Anchored = true
    p.CanCollide = true
    p.Transparency = 1
    p.CanQuery = false
    p.CanTouch = false
    p.Material = Enum.Material.SmoothPlastic
    p.Parent = workspace
    DR.plat = p
    return p
end
function DR.target()
    local pts = D.locations()
    for _, p in ipairs(A.spawners()) do pts[#pts + 1] = p end
    local root = T.mover()
    local far = {}
    for _, p in ipairs(pts) do if root and (Vector3.new(p.X, 0, p.Z) - Vector3.new(root.Position.X, 0, root.Position.Z)).Magnitude > 300 then far[#far + 1] = p end end
    local pick = far[math.random(1, math.max(1, #far))]
    if pick then return pick end
    if root then return root.Position + Vector3.new(math.random(-1500, 1500), 0, math.random(-1500, 1500)) end
    return nil
end
function DR.speed()
    local sp = S.speed
    local okc, c = gcall(M.VC and M.VC.getActiveChassisController)
    if okc and type(c) == "table" and not S.customSpeed then
        local ok, top = pcall(function()
            local ts = c.Tune.TransmissionSpeeds
            local em = num(c.PerformanceUpgrades and c.PerformanceUpgrades.EngineMult)
            return num(ts[#ts]) * (em > 0 and em or 1) * 0.77 * 2 + 2
        end)
        if ok and top > 10 then sp = math.min(sp, top * 0.85) end
    end
    return math.min(sp, speedCap())
end
function DR.loop(alive)
    while alive() do
        if not ensureCar(true) then noCar("drive")
        else
            local root, model = T.mover()
            local car = myCar()
            if root and car and inCar() then
                local _, size = car:GetBoundingBox()
                local bottom = size.Y / 2
                local cruise = root.Position.Y + S.height
                setStatus("drive", L["Lifting off"])
                T.go(Vector3.new(root.Position.X, cruise, root.Position.Z), { alive = alive, ground = true, tol = 3 })
                local plat = DR.platform()
                local platY = cruise - bottom - 0.5
                local dest = DR.target()
                local stuckAt, bestD = os.clock(), math.huge
                local last = root.Position
                while alive() and inCar() and dest do
                    local dt = RunService.Heartbeat:Wait()
                    root, model = T.mover()
                    if not root then break end
                    plat.CFrame = CFrame.new(root.Position.X, platY, root.Position.Z)
                    local flat = Vector3.new(dest.X - root.Position.X, 0, dest.Z - root.Position.Z)
                    local dist = flat.Magnitude
                    if dist < 40 then
                        dest = DR.target()
                        bestD, stuckAt = math.huge, os.clock()
                    else
                        local dir = flat.Unit
                        local sp = DR.speed()
                        local v = root.AssemblyLinearVelocity
                        root.AssemblyLinearVelocity = Vector3.new(dir.X * sp, math.min(v.Y, 0), dir.Z * sp)
                        pcall(T.face, model, root, dir)
                        if dist < bestD - 2 then bestD, stuckAt = dist, os.clock() end
                        if os.clock() - stuckAt > 3 then
                            platY = platY + 25
                            cruise = cruise + 25
                            T.go(Vector3.new(root.Position.X, cruise, root.Position.Z), { alive = alive, ground = true, tol = 3 })
                            bestD, stuckAt = math.huge, os.clock()
                        end
                        DR.miles = DR.miles + (root.Position - last).Magnitude * 0.0001551590380139643
                        last = root.Position
                        setStatus("drive", string.format(L["Driving  ·  %d mph  ·  %.1f mi"], math.floor(sp * MPH), DR.miles))
                    end
                end
                T.stop()
            else
                task.wait(1)
            end
        end
        task.wait(0.2)
    end
    DR.clear()
    setStatus("drive", nil)
end

local RC = { state = nil, uuid = nil, runs = 0, finished = false, RU = safeRequire(find(Mods, "Shared.Races.RaceUtil")), RRC = safeRequire(find(Mods, "Shared.Races.RaceRemoteConfig")) }
onRemote("RaceStateUpdate", function(uuid, state)
    RC.uuid, RC.state = uuid, state
    if state == "ClientsideFinish" or state == "Finish" then RC.finished = true end
end)
function RC.tracks()
    local out = {}
    local ok, live = ycall(RC.RRC and RC.RRC.getTracks)
    if ok and type(live) == "table" then
        for k in pairs(live) do if type(k) == "string" then out[#out + 1] = k end end
    end
    if #out == 0 then
        local tn = type(M.RaceConst) == "table" and M.RaceConst.TrackNames
        for k, v in pairs(type(tn) == "table" and tn or {}) do out[#out + 1] = type(v) == "string" and v or k end
    end
    if #out == 0 then out = { "Circuit", "CrossCountry", "Drag", "Highway", "SofiaBay", "Drawbridge" } end
    table.sort(out)
    return out
end
function RC.info(track)
    local ok, ti = ycall(RC.RU and RC.RU.getTrackInfo, track)
    if ok and type(ti) == "table" then
        return (num(ti.MinTimeSeconds) > 0 and num(ti.MinTimeSeconds) or 60), math.max(1, num(ti.MaxLaps))
    end
    local db = type(M.RaceDB) == "table" and type(M.RaceDB.races) == "table" and M.RaceDB.races[track]
    local minT = db and num(db.MinTime) or 0
    return (minT > 0 and minT or 60), (db and math.max(1, num(db.MaxLaps)) or 1)
end
function RC.model()
    local ls = find(workspace, "Game.Races.LocalSession")
    for _, m in ipairs(ls and ls:GetChildren() or {}) do
        if m:FindFirstChild("Checkpoints") and m:FindFirstChild("Finish") then return m end
    end
    return nil
end
function RC.aim(part)
    local p = part.Position
    local half = part.Size.Y / 2
    if half > 5 then p = p - Vector3.new(0, half - 5, 0) end
    return p
end
RC.ctrl = safeRequire(find(Mods, "Client.Races.RaceController"))
function RC.progress()
    local ok, race = gcall(RC.ctrl and RC.ctrl.getCurrentRace)
    if not (ok and type(race) == "table") then return nil end
    local ok2, rd = gcall(race.GetRacerData, race, lp)
    if ok2 and type(rd) == "table" then return num(rd.CheckpointNum), num(rd.Lap), rd.HasFinished end
    return nil
end
function RC.ground(pos, car)
    local params = RaycastParams.new()
    params.FilterType = Enum.RaycastFilterType.Include
    params.FilterDescendantsInstances = { workspace.Terrain }
    local hit = workspace:Raycast(pos + Vector3.new(0, 60, 0), Vector3.new(0, -200, 0), params)
    return hit and hit.Position.Y or nil
end
function RC.follow(cps, finishPart, laps, speed, alive, track)
    local total = #cps * laps + (finishPart and 1 or 0)
    local myIdx = 1
    local lastKey, lastChange = nil, os.clock()
    while alive() do
        local root, model = T.mover()
        if not root then return false end
        local cp, lap, done = RC.progress()
        if done then return true end
        local target, idx
        if cp then
            if cp == #cps and lap >= laps then
                target, idx = finishPart, total
            else
                local nxt = cp % #cps + 1
                target, idx = cps[nxt], math.max(0, lap - (cp == #cps and 0 or 1)) * #cps + nxt
                if lap == 0 then idx = nxt end
            end
        else
            local seq = math.min(myIdx, total)
            if finishPart and seq == total then target = finishPart else target = cps[(seq - 1) % #cps + 1] end
            idx = seq
        end
        if not target then return false end
        local key = tostring(cp) .. ":" .. tostring(lap) .. ":" .. myIdx
        if key ~= lastKey then lastKey, lastChange = key, os.clock() end
        setStatus("race", string.format(L["Racing %s  ·  %d/%d"], track, math.min(idx, total), total))
        local aim = target.Position
        local d = aim - root.Position
        if not cp and d.Magnitude < 14 then myIdx = myIdx + 1 end
        if os.clock() - lastChange > 8 then
            local car = myCar()
            if car then
                authorize()
                local off = root.CFrame:ToObjectSpace(car:GetPivot())
                local back = Vector3.new(d.X, 0, d.Z)
                back = back.Magnitude > 1 and back.Unit or Vector3.new(0, 0, 1)
                local from = aim - back * 25
                local gy = RC.ground(from, car)
                if gy and from.Y < gy + 4 then from = Vector3.new(from.X, gy + 4, from.Z) end
                car:PivotTo(CFrame.lookAt(from, from + back) * off)
            end
            lastChange = os.clock()
        end
        RunService.Heartbeat:Wait()
        local vel = (d.Magnitude > 0.1 and d.Unit or Vector3.zero) * speed
        local gy = RC.ground(root.Position, myCar())
        if gy and root.Position.Y < gy + 3 then
            vel = Vector3.new(vel.X, math.max(vel.Y, (gy + 3 - root.Position.Y) * 12), vel.Z)
        end
        root.AssemblyLinearVelocity = vel
        root.AssemblyAngularVelocity = Vector3.zero
        pcall(T.face, model, root, d.Magnitude > 0.1 and d.Unit or Vector3.new(0, 0, 1))
    end
    return false
end
function RC.loop(alive)
    while alive() do
        if not ensureCar(true) then noCar("race")
        else
            local track = S.raceTrack
            RC.state, RC.finished = nil, false
            setStatus("race", L["Starting "] .. track)
            fire("RaceStartTimeTrial", track, "NoOne")
            local t0 = os.clock()
            while alive() and RC.state ~= "Racing" and os.clock() - t0 < 45 do
                if RC.state then setStatus("race", L["Get ready  ·  "] .. tostring(RC.state)) end
                task.wait(0.2)
            end
            local model = RC.model()
            if not alive() then break end
            if RC.state ~= "Racing" or not model then
                setStatus("race", L["Race didn't start, retrying"])
                task.wait(4)
            else
                local cps = {}
                for _, c in ipairs(model.Checkpoints:GetChildren()) do
                    if c:IsA("BasePart") and tonumber(c.Name) then cps[#cps + 1] = c end
                end
                table.sort(cps, function(a, b) return tonumber(a.Name) < tonumber(b.Name) end)
                local finish = model:FindFirstChild("Finish")
                local finishPart = finish and (finish:IsA("BasePart") and finish or finish:FindFirstChildWhichIsA("BasePart", true))
                local minT, laps = RC.info(track)
                local path = {}
                for _ = 1, laps do for _, c in ipairs(cps) do path[#path + 1] = RC.aim(c) end end
                if finishPart then path[#path + 1] = RC.aim(finishPart) end
                local root = T.mover()
                local len, prev = 0, root and root.Position or path[1]
                for _, p in ipairs(path) do len = len + (p - prev).Magnitude prev = p end
                local sp = math.clamp(len / (minT * S.racePace), 30, speedCap())
                local racing = function() return alive() and RC.state == "Racing" end
                S.gliding = true
                authorize()
                S.racing = true
                RC.follow(cps, finishPart, laps, sp, racing, track)
                S.racing = false
                T.stop()
                local t1 = os.clock()
                while alive() and RC.state == "Racing" and not RC.finished and os.clock() - t1 < 10 do task.wait(0.2) end
                if RC.finished then
                    RC.runs = RC.runs + 1
                    setStatus("race", L["Finished "] .. track)
                else
                    setStatus("race", L["Race didn't count, retrying"])
                end
                task.wait(4)
            end
        end
        task.wait(0.5)
    end
    S.gliding = false
    setStatus("race", nil)
end

local V = { input = safeRequire(find(Mods, "Client.Vehicles.InputController")), nc = nil }
function V.ctrl()
    if not M.VC then return nil end
    local ok, c = gcall(M.VC.getActiveChassisController)
    return ok and type(c) == "table" and c or nil
end
function V.throttle(c)
    if V.input then
        local ok, t = gcall(V.input.Get)
        if ok and type(t) == "number" then return t end
    end
    return num(c and (c.InputThrottle or c.Throttle))
end
track(RunService.Heartbeat:Connect(function(dt)
    if not RUNNING then return end
    local car = myCar()
    if car then
        local mode = (S.gliding and (S.flyNoclip or S.racing or S.charNC)) and "full" or (S.noclip and "body" or nil)
        if mode or V.nc then
            pcall(NC.set, car, mode)
            V.nc = mode
        end
    end
    local c = V.ctrl()
    if not c then return end
    pcall(function()
        if S.nitro and type(c.Tune) == "table" and num(c.Tune.NitrousSupplyTime) > 0 then
            c.CurrentBoostSupply = c.Tune.NitrousSupplyTime
        end
        if S.noCap then c.ExternalMaxSpeedMPH = nil end
    end)
    pcall(V.applyTune, c)
    if not (S.customSpeed and inCar()) or S.gliding then return end
    pcall(function()
        local seat = car and car:FindFirstChild("VehicleSeat")
        local root = carRoot(car)
        if not (seat and root) then return end
        local thr = V.inputs(c)
        local fwd = seat.CFrame.LookVector
        fwd = Vector3.new(fwd.X, 0, fwd.Z)
        if fwd.Magnitude < 0.1 then return end
        fwd = fwd.Unit
        local v = root.AssemblyLinearVelocity
        local along = v:Dot(fwd)
        local roots = V.assemblies(car)
        if thr > 0 then
            local target = S.topMph / MPH
            if along < target then
                local delta = fwd * math.min(target - along, S.accel * dt)
                for _, r in ipairs(roots) do r.AssemblyLinearVelocity = r.AssemblyLinearVelocity + delta end
            end
        elseif thr < 0 and along > 1 then
            local delta = -fwd * math.min(along, S.brake * dt)
            for _, r in ipairs(roots) do r.AssemblyLinearVelocity = r.AssemblyLinearVelocity + delta end
        end
        local rec = V.tunes[c]
        if rec and along > rec.stock * 0.9 then
            local cf = root.CFrame
            local local_av = cf:VectorToObjectSpace(root.AssemblyAngularVelocity)
            root.AssemblyAngularVelocity = cf:VectorToWorldSpace(Vector3.new(local_av.X * 0.85, local_av.Y, local_av.Z * 0.85))
        end
    end)
end))

function V.inputs(c)
    if V.input and type(V.input.Get) == "function" then
        local co = coroutine.create(function() return pcall(V.input.Get) end)
        local r = table.pack(coroutine.resume(co))
        if r[1] and r[2] and type(r[3]) == "number" then return r[3], num(r[4]) end
    end
    return num(c and (c.InputThrottle or c.Throttle)), 0
end
V.asm = setmetatable({}, { __mode = "k" })
function V.assemblies(car)
    local rec = V.asm[car]
    if rec and os.clock() - rec.t < 1 then return rec.list end
    local seen, list = {}, {}
    for _, d in ipairs(car:GetDescendants()) do
        if d:IsA("BasePart") and not d.Anchored then
            local r = d.AssemblyRootPart
            if r and not seen[r] then seen[r] = true list[#list + 1] = r end
        end
    end
    V.asm[car] = { t = os.clock(), list = list }
    return list
end
function V.topOf(tune, c)
    local ts = type(tune) == "table" and tune.TransmissionSpeeds
    local top = type(ts) == "table" and num(ts[#ts]) or 0
    local em = type(c.PerformanceUpgrades) == "table" and num(c.PerformanceUpgrades.EngineMult) or 1
    if em <= 0 then em = 1 end
    return top * em * 0.77 * 2 + 2
end
V.tunes = setmetatable({}, { __mode = "k" })
function V.applyTune(c)
    local rec = V.tunes[c]
    if rec and c.Tune ~= rec.mod and c.Tune ~= rec.orig then rec = nil V.tunes[c] = nil end
    if S.customSpeed and not S.gliding then
        local orig = rec and rec.orig or c.Tune
        if type(orig) ~= "table" or type(orig.TransmissionSpeeds) ~= "table" then return end
        local stock = V.topOf(orig, c)
        if stock <= 2 then return end
        local k = math.max(1, (S.topMph / MPH) / stock * 1.05)
        k = math.floor(k * 20 + 0.5) / 20
        if rec and rec.k == k and c.Tune == rec.mod then return end
        local mod = {}
        for key, val in pairs(orig) do mod[key] = val end
        local ts = {}
        for i, s in ipairs(orig.TransmissionSpeeds) do ts[i] = s * k end
        mod.TransmissionSpeeds = ts
        c.Tune = mod
        V.tunes[c] = { orig = orig, mod = mod, k = k, stock = stock }
    elseif rec then
        if c.Tune == rec.mod then c.Tune = rec.orig end
        V.tunes[c] = nil
    end
end
onClean(function()
    for c, rec in pairs(V.tunes) do pcall(function() if c.Tune == rec.mod then c.Tune = rec.orig end end) end
end)

