    local Sv = Tabs.Settings:AddLeftGroupbox(L["Server"], "server")
    Sv:AddButton({ Text = L["Rejoin"], Func = function() pcall(function() TeleportService:TeleportToPlaceInstance(game.PlaceId, game.JobId, lp) end) end })
    Sv:AddButton({ Text = L["Server Hop"], Func = function()
        task.spawn(function()
            local ok, body = pcall(function() return game:HttpGet("https://games.roblox.com/v1/games/" .. game.PlaceId .. "/servers/Public?sortOrder=Asc&limit=100") end)
            if not ok then notify(L["Couldn't load servers"]) return end
            local okd, dat = pcall(function() return HttpService:JSONDecode(body) end)
            for _, s in ipairs(okd and dat and dat.data or {}) do
                if s.id ~= game.JobId and num(s.playing) < num(s.maxPlayers) then
                    pcall(function() TeleportService:TeleportToPlaceInstance(game.PlaceId, s.id, lp) end)
                    return
                end
            end
            notify(L["No other servers found"])
        end)
    end })
end)

task.spawn(function()
    local lastPlay, lastQuest, lastInc = 0, 0, 0
    while RUNNING do
        local now = os.clock()
        if on("de_playtime") and now - lastPlay > 30 then lastPlay = now pcall(RW.playtime) end
        if on("de_quests") and now - lastQuest > 25 then lastQuest = now pcall(RW.quests) end
        if on("de_incent") and now - lastInc > 300 then lastInc = now pcall(function() invoke("IncentivesClaimReward") fire("ClaimRewards") end) end
        task.wait(2)
    end
end)

task.spawn(function()
    S.startCash = cash()
    local t0 = os.clock()
    while RUNNING do
        pcall(function()
            local mins = math.floor((os.clock() - t0) / 60)
            local gain = cash() - (S.startCash or 0)
            local head = string.format("Session %dm  ·  +$%s", mins, abbrev(math.max(gain, 0)))
            labels.rob:SetText((S.status.rob or (on("de_atm") and L["Starting"] or L["Off"])) .. string.format(L["\nRobbed %d  ·  Cashed out %d"], A.busts, A.cashouts) .. (A.lastFail and (L["\nLast fail: "] .. A.lastFail) or ""))
            labels.del:SetText((S.status.del or (on("de_delivery") and L["Starting"] or L["Off"])) .. L["\nDelivered "] .. D.done .. (D.fail and (L["  ·  last: "] .. tostring(D.fail)) or ""))
            labels.pol:SetText((S.status.pol or ((on("de_scenes") or on("de_arrest")) and L["Starting"] or L["Off"])) .. string.format(L["\nScenes %d  ·  Arrests %d"], P.cleared, P.arrests))
            labels.drive:SetText((S.status.drive or (on("de_drive") and L["Starting"] or L["Off"])) .. "\n" .. head)
            labels.race:SetText((S.status.race or (on("de_race") and L["Starting"] or L["Off"])) .. L["\nRaces done "] .. RC.runs)
            local c = V.ctrl()
            labels.car:SetText(c and string.format(L["%d mph"], math.floor(num(c.SpeedMPH))) or L["Not driving"])
            labels.rw:SetText(head)
        end)
        task.wait(0.5)
    end
end)

local function unload()
    pcall(function() for _, k in ipairs(FARMS) do if on(k) then Toggles[k]:SetValue(false) end end end)
    pcall(T.stop)
    pcall(function() if _G.__CW_DE_CLEAN then _G.__CW_DE_CLEAN() end end)
    pcall(function() Library:Unload() end)
end
local MenuBox = Tabs.Settings:AddRightGroupbox(L["Menu"], "menu")
MenuBox:AddLabel(L["Menu Toggle"]):AddKeyPicker("MenuKeybind", { Default = "RightShift", NoUI = true, Text = L["Menu Toggle"] })
MenuBox:AddButton("Unload", unload)
Library.ToggleKeybind = Opt.MenuKeybind

SaveManager:SetLibrary(Library)
ThemeManager:SetLibrary(Library)
SaveManager:IgnoreThemeSettings()
SaveManager:SetIgnoreIndexes({ "MenuKeybind", "FeedbackType", "FeedbackMsg", "de_code", "de_atm", "de_delivery", "de_scenes", "de_arrest", "de_drive", "de_race" })
ThemeManager:SetFolder("DrivingEmpire")
SaveManager:SetFolder("DrivingEmpire")
ThemeManager:ApplyToTab(Tabs.Settings)
SaveManager:BuildConfigSection(Tabs.Settings)
SaveManager:LoadAutoloadConfig()
if S.hookless then notify(L["Safety hook unavailable: speeds capped"]) end

end
